// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "forge-std/Test.sol";

// Standalone reproduction of SingleProviderHelper._calculateOutputLPAndProtocolFee overflow
// References: SingleProviderHelper.sol lines 160-179 vs FixedHelper.sol lines 1057-1084
contract SingleProviderOverflowTest is Test {
    uint256 constant MAX_BPS = 10000;
    uint256 constant Q96 = 2 ** 96;
    uint160 constant MIN_SQRT_RATIO = 4295128739;

    // Replicates SingleProviderHelper._calculateOutputLPAndProtocolFee (lines 160-179)
    function _calculateOutputFee_NoGuard(
        uint256 reserveAmountIn,
        uint16 poolFeeBPS,
        uint16 protocolFeeBPS
    ) internal pure returns (uint256 amountInAfterFees, uint256 lpFeeAmount, uint256 protocolFeeAmount) {
        lpFeeAmount = _mulDivRoundingUp(reserveAmountIn, poolFeeBPS, MAX_BPS - poolFeeBPS);
        unchecked {
            amountInAfterFees = reserveAmountIn + lpFeeAmount; // NO overflow check (line 171)
        }
        if (protocolFeeBPS > 0) {
            protocolFeeAmount = _mulDiv(lpFeeAmount, protocolFeeBPS, MAX_BPS);
            unchecked { lpFeeAmount -= protocolFeeAmount; }
        }
    }

    // Replicates FixedHelper._calculateOutputLPAndProtocolFee (lines 1057-1084)
    function _calculateOutputFee_WithGuard(
        uint256 reserveAmountIn,
        uint16 poolFeeBPS,
        uint16 protocolFeeBPS
    ) internal pure returns (uint256 amountInAfterFees, uint256 lpFeeAmount, uint256 protocolFeeAmount) {
        lpFeeAmount = _mulDivRoundingUp(reserveAmountIn, poolFeeBPS, MAX_BPS - poolFeeBPS);
        unchecked {
            amountInAfterFees = reserveAmountIn + lpFeeAmount;
            if (amountInAfterFees < lpFeeAmount) revert("FixedPool__Overflow"); // line 1070-1072
        }
        if (protocolFeeBPS > 0) {
            protocolFeeAmount = _mulDiv(lpFeeAmount, protocolFeeBPS, MAX_BPS);
            unchecked { lpFeeAmount -= protocolFeeAmount; }
        }
    }

    // Replicates SingleProviderHelper.calculateFixedOutput (lines 192-204)
    function _calculateFixedOutput(uint256 amountOut, uint160 sqrtPriceX96, bool zeroForOne) internal pure returns (uint256 amountIn) {
        if (zeroForOne) {
            amountIn = _mulDivRoundingUp(amountOut, Q96, sqrtPriceX96);
            amountIn = _mulDivRoundingUp(amountIn, Q96, sqrtPriceX96);
        } else {
            amountIn = _mulDivRoundingUp(amountOut, sqrtPriceX96, Q96);
            amountIn = _mulDivRoundingUp(amountIn, sqrtPriceX96, Q96);
        }
    }

    function _mulDiv(uint256 a, uint256 b, uint256 d) internal pure returns (uint256) {
        return (a * b) / d; // simplified; real uses FullMath
    }

    function _mulDivRoundingUp(uint256 a, uint256 b, uint256 d) internal pure returns (uint256 result) {
        result = (a * b) / d;
        if (mulmod(a, b, d) > 0) result++;
    }

    function test_overflowInSingleProviderHelper() public pure {
        // reserveAmountIn in the overflow-prone range: ~2^255
        uint256 reserveAmountIn = (type(uint256).max / 2) + 1; // = 2^255
        uint16 poolFeeBPS = 5001; // just over 50%
        uint16 protocolFeeBPS = 0;

        // SingleProviderHelper version: silently wraps
        (uint256 noGuardTotal, uint256 noGuardFee, ) = _calculateOutputFee_NoGuard(reserveAmountIn, poolFeeBPS, protocolFeeBPS);

        // Overflow detection: if sum wrapped, total < both addends
        bool overflowed = noGuardTotal < reserveAmountIn || noGuardTotal < noGuardFee;
        assertTrue(overflowed, "SingleProviderHelper: overflow should occur at 2^255 with 50.01% fee");

        // FixedHelper version: reverts
        vm.expectRevert("FixedPool__Overflow");
        _calculateOutputFee_WithGuard(reserveAmountIn, poolFeeBPS, protocolFeeBPS);
    }

    function test_calculateFixedOutput_producesLargeReserveAmountIn() public pure {
        // zeroForOne with MIN_SQRT_RATIO: amountIn = amountOut * (Q96/sqrtPrice)^2 ~= amountOut * 2^128
        uint256 amountOut = 1 << 127;
        uint160 sqrtPrice = MIN_SQRT_RATIO + 1; // just above min to avoid edge

        uint256 reserveAmountIn = _calculateFixedOutput(amountOut, sqrtPrice, true);

        // Should be ~2^127 * 2^128 = 2^255
        assertGt(reserveAmountIn, type(uint256).max / 4, "reserveAmountIn should be in overflow-prone range (>2^254)");
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "forge-std/Test.sol";

// Standalone test for FixedHelper.collectFees Q128 truncation compounding
// References: FixedHelper.sol lines 577-580
contract FixedHelperFeeRoundingTest is Test {
    uint256 constant Q128 = 2 ** 128;

    // Replicates the collectFees calculation at FixedHelper lines 577-580
    function _collectFees_current(
        uint256 feeGrowthInside0Of0X128,
        uint256 feeGrowthInside0Of1X128,
        uint256 feeGrowthInside1Of0X128,
        uint256 feeGrowthInside1Of1X128
    ) internal pure returns (uint256 fee0, uint256 fee1) {
        // Current: four independent Q128 divisions (lines 577-580)
        fee0 = feeGrowthInside0Of0X128 / Q128 + feeGrowthInside0Of1X128 / Q128;
        fee1 = feeGrowthInside1Of0X128 / Q128 + feeGrowthInside1Of1X128 / Q128;
    }

    // Optimal: sum growth deltas before single division
    function _collectFees_optimal(
        uint256 feeGrowthInside0Of0X128,
        uint256 feeGrowthInside0Of1X128,
        uint256 feeGrowthInside1Of0X128,
        uint256 feeGrowthInside1Of1X128
    ) internal pure returns (uint256 fee0, uint256 fee1) {
        fee0 = (feeGrowthInside0Of0X128 + feeGrowthInside0Of1X128) / Q128;
        fee1 = (feeGrowthInside1Of0X128 + feeGrowthInside1Of1X128) / Q128;
    }

    function test_collectFees_worstCaseTruncation() public pure {
        // Each growth delta = Q128 - 1 maximizes per-division truncation
        uint256 growthDelta = Q128 - 1;

        (uint256 fee0_current, uint256 fee1_current) = _collectFees_current(
            growthDelta, growthDelta, growthDelta, growthDelta
        );
        (uint256 fee0_optimal, uint256 fee1_optimal) = _collectFees_optimal(
            growthDelta, growthDelta, growthDelta, growthDelta
        );

        // Current: each (Q128-1)/Q128 = 0. Total fee0 = 0+0 = 0
        assertEq(fee0_current, 0, "Current impl truncates each term to 0");
        assertEq(fee1_current, 0, "Current impl truncates each term to 0");

        // Optimal: (2*(Q128-1)) / Q128 = 1. Total fee0 = 1
        assertEq(fee0_optimal, 1, "Optimal impl preserves value by summing first");
        assertEq(fee1_optimal, 1, "Optimal impl preserves value by summing first");

        // Demonstrate loss: current loses 1 wei per token per collection
        assertGt(fee0_optimal, fee0_current, "Truncation causes measurable loss vs optimal");
    }

    function test_collectFees_cumulativeLoss() public pure {
        uint256 totalLoss = 0;
        uint256 iterations = 1000;

        for (uint256 i = 1; i <= iterations; i++) {
            // Simulate varying small fee growth deltas
            uint256 delta0 = (Q128 / 2) + i;
            uint256 delta1 = (Q128 / 3) + i;

            (uint256 current0, ) = _collectFees_current(delta0, delta1, 0, 0);
            (uint256 optimal0, ) = _collectFees_optimal(delta0, delta1, 0, 0);

            if (optimal0 > current0) {
                totalLoss += optimal0 - current0;
            }
        }

        assertGt(totalLoss, 0, "Cumulative truncation loss over 1000 collections should be non-zero");
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "forge-std/Test.sol";

// Demonstrates asymmetric safety in FixedHelper height tracking
// References: _increaseHeight line 1866 (no guard) vs _decreaseHeight lines 1763-1767 (has guard)
contract FixedHeightAsymmetryTest is Test {
    struct HeightState {
        uint256 consumedLiquidity;
    }

    // Simulates _increaseHeight at FixedHelper line 1866
    function _increaseHeight(HeightState memory height, uint256 amount) internal pure {
        if (amount > 0) {
            unchecked {
                height.consumedLiquidity += amount; // Line 1866: NO overflow check
            }
        }
    }

    // Simulates _decreaseHeight at FixedHelper lines 1753-1767
    function _decreaseHeight(HeightState memory height, uint256 amount) internal pure {
        if (amount > 0) {
            if (height.consumedLiquidity < amount) {
                revert("FixedPool__UnderflowConsumedLiquidity"); // Lines 1765-1767
            }
            unchecked {
                height.consumedLiquidity -= amount;
            }
        }
    }

    function test_increaseHeight_overflows_silently() public pure {
        HeightState memory height;
        height.consumedLiquidity = type(uint256).max - 100;

        _increaseHeight(height, 200);

        // Should be (max-100)+200 = max+100, but wraps to 99
        assertEq(height.consumedLiquidity, 99, "consumedLiquidity wrapped to 99");
        assertLt(height.consumedLiquidity, 200, "Wrapped value is less than the amount just added");
    }

    function test_decreaseHeight_reverts_on_underflow() public {
        HeightState memory height;
        height.consumedLiquidity = 100;

        vm.expectRevert("FixedPool__UnderflowConsumedLiquidity");
        _decreaseHeight(height, 200);
    }

    function test_increaseHeight_wrappedState_breaksReserveCalc() public pure {
        HeightState memory height;
        // Simulate near-max consumed
        height.consumedLiquidity = type(uint256).max - 50;
        uint256 preOverflow = height.consumedLiquidity;

        _increaseHeight(height, 100);

        // After wrap: consumedLiquidity = 49 (tiny)
        assertEq(height.consumedLiquidity, 49, "Wrapped consumedLiquidity");

        // A reserve calculation based on consumedLiquidity would see 49 consumed
        // when the actual consumption is type(uint256).max - 50 + 100
        // This makes the pool appear to have nearly full reserves
        assertLt(height.consumedLiquidity, preOverflow, "Wrapped value falsely indicates low consumption");
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "forge-std/Test.sol";

// Demonstrates stale reserve read pattern in SingleProviderPoolType
// References: SingleProviderPoolType.sol lines 312, 323-326, 397, 408-412
contract StaleReserveReadTest is Test {
    uint128 public reserve0 = 1000e18;
    uint128 public reserve1 = 1000e18;
    bool public hookWasCalled;

    // Simulates the SingleProviderPoolType.swapByInput flow (lines 312-333)
    function simulateSwapFlow() public returns (uint128 cachedReserve, uint128 actualReserve) {
        // Step 1: Read reserves via VIEW call (line 312)
        cachedReserve = reserve1;

        // Step 2: Call hook for price (line 323-326)
        // Hook side-effect: modifies reserves during callback
        _mockHookGetPoolPriceForSwap();

        // Step 3: Use cachedReserve for swap calculations
        actualReserve = reserve1;
    }

    function _mockHookGetPoolPriceForSwap() internal {
        // Hook atomically removes liquidity, reducing reserves
        reserve1 -= 500e18;
        hookWasCalled = true;
    }

    function test_staleReserveReadDesync() public {
        (uint128 cached, uint128 actual) = simulateSwapFlow();

        assertEq(cached, 1000e18, "Cached reserve reflects pre-hook state");
        assertEq(actual, 500e18, "Actual reserve reflects post-hook state");
        assertGt(cached, actual, "DESYNC: swap uses stale reserve (1000e18) but actual is (500e18)");
        assertTrue(hookWasCalled, "Hook was called between read and use");

        // The swap would cap output at cached (1000e18) instead of actual (500e18)
        uint128 swapOutputCap = cached; // line 317-320: swapCache.reserveOut = poolState.reserve
        assertGt(swapOutputCap, actual, "Output cap exceeds actual available reserves");
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "forge-std/Test.sol";

// Tests fee formula divergence in SingleProviderHelper swapByInput fallback
// References: SingleProviderHelper.sol _calculateInputLPAndProtocolFee (line 69)
//             vs _calculateOutputLPAndProtocolFee (line 160)
contract FeeFormulaAsymmetryTest is Test {
    uint256 constant MAX_BPS = 10000;

    // Replicates _calculateInputLPAndProtocolFee (lines 69-88)
    function inputFee(uint256 amountIn, uint16 feeBPS) internal pure returns (uint256 lpFee, uint256 netInput) {
        lpFee = _ceilDiv(amountIn * feeBPS, MAX_BPS);
        netInput = amountIn - lpFee;
    }

    // Replicates _calculateOutputLPAndProtocolFee (lines 160-179)
    function outputFee(uint256 reserveAmountIn, uint16 feeBPS) internal pure returns (uint256 lpFee, uint256 totalInput) {
        lpFee = _ceilDiv(reserveAmountIn * feeBPS, MAX_BPS - feeBPS);
        totalInput = reserveAmountIn + lpFee;
    }

    function _ceilDiv(uint256 a, uint256 b) internal pure returns (uint256) {
        return (a + b - 1) / b;
    }

    function test_feeFormulaDivergence_singleSwap() public pure {
        uint16 feeBPS = 300; // 3%
        uint256 amountIn = 1e18 + 7; // odd amount to provoke rounding

        // Input path: deduct fee from amountIn
        (uint256 inFee, uint256 netInput) = inputFee(amountIn, feeBPS);

        // Output path: given netInput as reserve requirement, compute required total
        (uint256 outFee, uint256 totalRequired) = outputFee(netInput, feeBPS);

        // If formulas were perfectly inverse, totalRequired == amountIn
        // Rounding makes them differ
        uint256 diff = totalRequired > amountIn ? totalRequired - amountIn : amountIn - totalRequired;
        assertLe(diff, 2, "Per-swap divergence bounded at 2 wei");
    }

    function test_feeFormulaDivergence_cumulative() public pure {
        uint16 feeBPS = 500; // 5%
        uint256 cumulativeDrift = 0;

        for (uint256 i = 1; i <= 1000; i++) {
            uint256 amountIn = 1e18 + i;
            (uint256 inFee, uint256 netInput) = inputFee(amountIn, feeBPS);
            (uint256 outFee, uint256 totalRequired) = outputFee(netInput, feeBPS);

            if (totalRequired != amountIn) {
                cumulativeDrift += (totalRequired > amountIn)
                    ? totalRequired - amountIn
                    : amountIn - totalRequired;
            }
        }

        assertGt(cumulativeDrift, 0, "Cumulative rounding drift should be measurable over 1000 swaps");
        emit log_named_uint("Total cumulative drift (wei)", cumulativeDrift);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "forge-std/Test.sol";

// Demonstrates _crossHeight fee growth outside flip behavior under oscillation
// References: FixedHelper.sol _crossHeight lines 2015-2019
contract FixedHeightFeeOscillationTest is Test {
    uint256 constant Q128 = 2 ** 128;

    // Simulated height state
    uint256 public feeGrowthGlobalX128;
    uint256 public feeGrowthOutsideAtBoundary;
    uint256 public currentHeight;

    function setUp() public {
        feeGrowthGlobalX128 = 100 * Q128;
        feeGrowthOutsideAtBoundary = 50 * Q128; // initialized at pool creation
        currentHeight = 199; // just below boundary at 200
    }

    // Simulates _crossHeight (lines 2016-2017) going up
    function _crossUp() internal {
        feeGrowthOutsideAtBoundary = feeGrowthGlobalX128 - feeGrowthOutsideAtBoundary;
        currentHeight = 200;
    }

    // Simulates _crossHeight (lines 2016-2017) going down
    function _crossDown() internal {
        feeGrowthOutsideAtBoundary = feeGrowthGlobalX128 - feeGrowthOutsideAtBoundary;
        currentHeight = 199;
    }

    // Simulates fee growth from a swap
    function _addSwapFees(uint256 feeX128) internal {
        feeGrowthGlobalX128 += feeX128;
    }

    // getFeeGrowthInside for position BELOW boundary (heights 100-200)
    function _feeGrowthInsideBelow() internal view returns (uint256) {
        if (currentHeight < 200) {
            return feeGrowthGlobalX128 - feeGrowthOutsideAtBoundary;
        } else {
            return feeGrowthOutsideAtBoundary;
        }
    }

    // getFeeGrowthInside for position ABOVE boundary (heights 200-300)
    function _feeGrowthInsideAbove() internal view returns (uint256) {
        if (currentHeight >= 200) {
            return feeGrowthGlobalX128 - feeGrowthOutsideAtBoundary;
        } else {
            return feeGrowthOutsideAtBoundary;
        }
    }

    function test_oscillationShiftsFeeAttribution() public {
        uint256 belowBefore = _feeGrowthInsideBelow();
        uint256 aboveBefore = _feeGrowthInsideAbove();

        // Oscillation cycle: cross up, generate swap fees, cross back down
        _crossUp();
        _addSwapFees(10 * Q128); // fees from first swap
        _crossDown();
        _addSwapFees(10 * Q128); // fees from second swap

        uint256 belowAfter = _feeGrowthInsideBelow();
        uint256 aboveAfter = _feeGrowthInsideAbove();

        uint256 belowAccrued = belowAfter - belowBefore;
        uint256 aboveAccrued = aboveAfter - aboveBefore;

        emit log_named_uint("Fee accrued to below-boundary position (Q128)", belowAccrued / Q128);
        emit log_named_uint("Fee accrued to above-boundary position (Q128)", aboveAccrued / Q128);

        // Total fees = 20 * Q128. Both positions should get proportional share.
        // If oscillation causes asymmetric attribution, one side gets more.
        uint256 totalAccrued = belowAccrued + aboveAccrued;
        assertEq(totalAccrued, 20 * Q128, "Total fee attribution should equal total fees generated");

        // The key test: did the oscillation create asymmetric fee distribution?
        // In a fair system with current below boundary, the first swap fees (above)
        // go to above positions, second swap fees (below) go to below positions.
        // The flip pattern may attribute differently.
        bool asymmetric = belowAccrued != aboveAccrued;
        if (asymmetric) {
            emit log_string("ASYMMETRIC: oscillation shifted fee attribution between positions");
            uint256 shift = belowAccrued > aboveAccrued
                ? belowAccrued - aboveAccrued
                : aboveAccrued - belowAccrued;
            assertGt(shift, 0, "Fee attribution shift detected from height oscillation");
        }
    }
}
